import { Link } from 'react-router-dom';
import { useStore } from '../context/StoreContext';
import './ProductCard.css';

function formatPrice(product) {
  if (product.price === null || product.price === undefined || Number.isNaN(Number(product.price))) return 'Check price';
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: product.currency || 'USD' }).format(product.price);
  } catch {
    return `${product.currency || '$'} ${product.price}`;
  }
}

function ProductCard({ product }) {
  const { addToCart, toggleWishlist, openProduct, wishlist } = useStore();
  const id = product.id || product.productId;
  const saved = wishlist.some((item) => (item.id || item.productId) === id);

  return (
    <article className="product-card">
      <div className="product-image-wrap">
        {product.image ? <img src={product.image} alt={product.title} loading="lazy" /> : <div className="no-image">No Image</div>}
        <span className="source-pill">{product.source}</span>
        <button className={`wish-btn ${saved ? 'saved' : ''}`} onClick={() => toggleWishlist(product)} aria-label="Save to wishlist">
          {saved ? '♥' : '♡'}
        </button>
      </div>
      <div className="product-card-body">
        <div className="product-meta">
          <span>{product.category || 'Technology'}</span>
          <span>{product.brand || 'Unknown'}</span>
        </div>
        <h3>{product.title}</h3>
        <p>{product.description || 'Live product result from external product provider.'}</p>
        <div className="rating-row">
          <span>★ {product.rating ? Number(product.rating).toFixed(1) : 'N/A'}</span>
          <span>{product.reviewCount || 0} reviews</span>
        </div>
        <div className="price-row">
          <strong>{formatPrice(product)}</strong>
          <span>{product.availability || 'Check seller'}</span>
        </div>
        <div className="product-actions">
          <button className="btn btn-primary" onClick={() => addToCart(product)}>Add</button>
          <button className="btn btn-secondary" onClick={() => openProduct(product)}>Quick View</button>
          <Link className="details-link" to={`/product/${encodeURIComponent(id)}`}>Details</Link>
        </div>
      </div>
    </article>
  );
}

export default ProductCard;
